effect.shader:
/** O croma de `x` em volta da luma do Sapphire, vezes `k` (medido: luma = (5 R + 8 G + 3 B) / 16). */
vec3 croma(vec3 x, float k) {
    float y = dot(x, vec3(0.3125, 0.5, 0.1875));
    return y + (x - y) * k;
}

void main() {
    ivec2 T = textureSize(inputImg, 0);
    vec4 c = texelFetch(inputImg, ivec2(min(floor(acScreenNorm * vec2(T)), vec2(T) - 1.0)), 0);
    float a = invertAlpha ? 1.0 - c.a : c.a;
    // Remult sem inverter o alfa: o "branco" de onde se subtrai é o alfa da fonte.
    float um = (remultByAlpha && !invertAlpha) ? c.a : 1.0;

    vec3 x = croma(invertLuma ? um - c.rgb : c.rgb, invertChroma == invertLuma ? 1.0 : -1.0);
    if (invertRed) x.r = um - x.r;
    if (invertGreen) x.g = um - x.g;
    if (invertBlue) x.b = um - x.b;

    vec3 claros = floor(tintLights.rgb * 255.0 + 0.5) / 255.0 * scaleLights;
    vec3 escuros = floor(tintDarks.rgb * 255.0 + 0.5) / 255.0 + offsetDarks;
    vec3 d = escuros + croma(x, saturation) * max(claros - escuros, vec3(0.0));
    if (remultByAlpha && invertAlpha) d *= a;
    fragColor = vec4(clamp(d, 0.0, 1.0), a);
}
